'use strict';

// MODULES //

var hasProp = require( '@stdlib/assert/has-property' );
var isScaleName = require( '@stdlib/plot/vega/base/assert/is-scale-name' );
var isString = require( '@stdlib/assert/is-string' ).isPrimitive;
var join = require( '@stdlib/array/base/join' );
var ctors = require( '@stdlib/plot/vega/scale-ctors' );
var scaleNames = require( '@stdlib/plot/vega/base/scales' );
var format = require( '@stdlib/string/format' );


// MAIN //

/**
* Returns a function for creating a named scale.
*
* @param {string} name - default scale name
* @param {string} type - default scale type
* @throws {TypeError} first argument must be a string
* @throws {TypeError} second argument must be a supported scale type
* @returns {Function} function for creating a named scale
*
* @example
* var xScale = factory( 'xScale', 'linear' );
*
* var scale = xScale();
* // returns <LinearScale>
*/
function factory( name, type ) {
	var defaults;
	if ( !isString( name ) ) {
		throw new TypeError( format( 'invalid argument. First argument must be a string. Value: `%s`.', name ) );
	}
	if ( !isScaleName( type ) ) {
		throw new TypeError( format( 'invalid argument. Second argument must be one of the following: "%s". Value: `%s`.', join( scaleNames(), ', ' ), type ) );
	}
	defaults = {
		'name': name,
		'type': type
	};
	return createScale;

	/**
	* Returns a named scale.
	*
	* @private
	* @param {Options} [options] - function options
	* @throws {TypeError} options argument must be an object
	* @throws {Error} must provide valid options
	* @returns {Scale} scale instance
	*/
	function createScale( options ) {
		var scale;
		var ctor;
		if ( arguments.length ) {
			if ( hasProp( options, 'type' ) ) {
				ctor = ctors( options.type );
				if ( ctor === null ) {
					throw new TypeError( format( 'invalid argument. Second argument must be one of the following: "%s". Value: `%s`.', join( scaleNames(), ', ' ), options.type ) );
				}
			} else {
				ctor = ctors( defaults.type );
			}
			scale = new ctor( options );
			if ( !hasProp( options, 'name' ) ) {
				scale.name = defaults.name;
			}
			return scale;
		}
		ctor = ctors( defaults.type );
		return new ctor( defaults );
	}
}


// EXPORTS //

module.exports = factory;
